wren:
/// Fruit Slicer — Fruit-Ninja-style swipe game wired through the
/// canonical asset-loading + scene-flow pattern, the same shape as
/// the in-tree desktop example at
/// `examples/game/fruit-slicer/main.wren`:
///
///   @hatch:assets/AssetLoader   resolves the atlas + manifest one
///                               item per loader.update tick so the
///                               splash bar can animate while the
///                               bytes stream in.
///   @hatch:fsm/StateChart       drives splash → loading → ready →
///                               playing → gameover (with an error
///                               terminal); each state owns its own
///                               update + draw.
///   @hatch:hud                  procedural 5×7 font + 1×1 white
///                               pixel for menu text, the loading
///                               bar, and the GAME OVER overlay.
///
/// Asset credits:
///   * Fruits asset pack by Lemon Balm — https://lemon-balm.itch.io/
///   * Heart HUD icon by Penzilla — https://penzilla.itch.io/
import "@hatch:game"   for Game
import "@hatch:gpu"    for Renderer2D, Camera2D, Sprite
import "@hatch:json"   for JSON
import "@hatch:assets" for AssetLoader
import "@hatch:fsm"    for StateChart
import "@hatch:hud"    for HUD

class FruitSlicer is Game {
  // Design-space size. Layout, hit boxes, mouse mapping, spawn
  // bounds, and miss-detection thresholds all key off these so
  // changing the canvas size only needs an edit here.
  static DESIGN_W { 640 }
  static DESIGN_H { 480 }

  construct new() {}

  config { {
    "title":      "Fruit Slicer",
    "width":      FruitSlicer.DESIGN_W,
    "height":     FruitSlicer.DESIGN_H,
    "clearColor": [0.04, 0.03, 0.08, 1.0],
    "canvas":     "stage-canvas"
  } }

  setup(g) {
    _renderer = Renderer2D.new(g.device, g.surfaceFormat)
    _camera   = Camera2D.contain(FruitSlicer.DESIGN_W, FruitSlicer.DESIGN_H, g.width, g.height)
    _hud      = HUD.new(g)      // for splash + loading bar + ready prompt
    _quad     = null            // built once the atlas resolves
    _manifest = null
    _atlas    = null
    _fruitNames = []

    // Scene-flow chart. Each transition is driven by a real
    // signal (timer expiry, AssetLoader callback, mouse click,
    // lives hitting zero) — no chart-internal auto-transitions.
    _chart = StateChart.build {|c|
      c.id("flow")
      c.initial("splash")
      c.state("splash")   {|s| s.on("ready",    "loading")  }
      c.state("loading")  {|s|
        s.on("loaded",    "ready")
        s.on("loadError", "error")
      }
      c.state("ready")    {|s| s.on("start",    "playing")  }
      c.state("playing")  {|s| s.on("gameover", "gameover") }
      c.state("gameover") {|s| s.on("restart",  "ready")    }
      c.state("error")    {|s|}    // terminal
    }
    _chart.start()

    // Splash timer — bumped each frame in update; flips the chart
    // into loading once the title's had time to read.
    _splashTimer  = 0
    _splashLength = 1.2

    // Browser.fetch is async-only in the browser. AssetLoader
    // expects synchronous closures, so we await the network calls
    // here in setup and queue the resolved values as closures that
    // return them on each tick. Same lifecycle as the desktop port
    // (queued → resolved one per loader.update); just the byte
    // source differs.
    var bytes    = Browser.fetchBytes("./assets/fruit-slicer/atlas.rgba8").await
    var jsonText = Browser.fetch("./assets/fruit-slicer/atlas.json").await
    _loader = AssetLoader.new()
    _loader.queue("manifest", Fn.new { JSON.parse(jsonText) })
    _loader.queue("bytes",    Fn.new { bytes })
    // Closures dispatch into methods so the heavy work runs in
    // method bodies rather than a closure body — the interpreter
    // path doesn't currently support every Wren idiom inside
    // closures, and methods sidestep that limitation cleanly.
    var self = this
    _loader.onError(Fn.new {|name, err| self.onLoadError_(name, err) })
    _loader.onComplete(Fn.new {|loaded| self.onAssetsLoaded_(g, loaded) })

    _loadFraction = 0
    _loadDone     = 0
    _loadTotal    = 0
    _loader.onProgress(Fn.new {|fraction, done, total|
      self.onLoadProgress_(fraction, done, total)
    })

    // Artificial inter-asset delay so the loading bar stays
    // visible long enough to read — real bytes resolve in
    // milliseconds.
    _loadingThrottle = 0
    _loadingDelay    = 0.6     // seconds per asset

    _seed = 1
    resetGame_
    System.print("Fruit Slicer — splash → loading → ready → playing")
  }

  resize(g, w, h) { _camera.fitContain(w, h) }

  // Draw `text` horizontally + vertically centred in the design
  // space, with `yOffset` shifting it above (negative) or below
  // (positive) the centre line.
  labelCentre_(text, yOffset, scale, color) {
    var size = HUD.measure(text, scale)
    // Snap to integer pixel coords so the sprite-batch vertex
    // floats stay clean — non-integer x/y are valid for the
    // shader but tiered JIT has been seen to corrupt fractional
    // arithmetic on hot closure-receiver paths.
    var x = ((FruitSlicer.DESIGN_W - size[0]) / 2).floor
    var y = (FruitSlicer.DESIGN_H / 2 + yOffset - size[1] / 2).floor
    _hud.label(text, x, y, scale, color)
  }

  onAssetsLoaded_(g, loaded) {
    _manifest = loaded["manifest"]
    var size  = _manifest["size"]
    _atlasW   = size[0]
    _atlasH   = size[1]
    _atlas = g.device.createTexture({
      "width":  _atlasW, "height": _atlasH,
      "format": "rgba8unorm",
      "usage":  ["texture-binding", "copy-dst"]
    })
    g.device.writeTexture(_atlas, loaded["bytes"], {
      "width": _atlasW, "height": _atlasH, "bytesPerRow": _atlasW * 4
    })
    _quad = Sprite.new(_atlas)
    _quad.anchor(0.5, 0.5)
    for (k in _manifest["sprites"].keys) _fruitNames.add(k)
    _chart.send("loaded")
  }

  onLoadProgress_(fraction, done, total) {
    _loadFraction = fraction
    _loadDone     = done
    _loadTotal    = total
  }

  onLoadError_(name, err) {
    System.print("asset '%(name)' failed: %(err)")
    _chart.send("loadError")
  }

  resetGame_ {
    _fruits = []
    _halves = []
    _trail  = []
    _score  = 0
    _lives  = 3
    _spawnTimer = 0.5
    _gameoverT  = 0
  }

  // Park-Miller minimal-standard LCG. seed*16807 peaks at ~3.6e13,
  // well under 2^53, so it stays exact in f64.
  rand_ {
    _seed = (_seed * 16807) % 2147483647
    return _seed / 2147483647
  }
  randRange_(lo, hi) { lo + (hi - lo) * rand_ }

  update(g) {
    if      (_chart.activeStates.contains("splash"))   updateSplash_(g)
    else if (_chart.activeStates.contains("loading"))  updateLoading_(g)
    else if (_chart.activeStates.contains("ready"))    updateReady_(g)
    else if (_chart.activeStates.contains("playing")) updatePlaying_(g)
    else if (_chart.activeStates.contains("gameover")) updateGameover_(g)
  }

  draw(g) {
    _renderer.beginFrame(_camera)
    _renderer.beginPass(g.pass)
    _hud.beginFrame(g, _renderer)
    if      (_chart.activeStates.contains("splash"))   drawSplash_(g)
    else if (_chart.activeStates.contains("loading"))  drawLoading_(g)
    else if (_chart.activeStates.contains("ready"))    drawReady_(g)
    else if (_chart.activeStates.contains("playing")) drawPlaying_(g)
    else if (_chart.activeStates.contains("gameover")) drawGameover_(g)
    else if (_chart.activeStates.contains("error"))    drawError_(g)
    _hud.endFrame
    _renderer.endPass()
    _renderer.flush(g.pass)
  }

  // ── Splash ─────────────────────────────────────────────────────

  updateSplash_(g) {
    _splashTimer = _splashTimer + g.dt
    if (_splashTimer >= _splashLength) {
      _chart.send("ready")              // splash → loading
      _loader.start()
    }
  }

  drawSplash_(g) {
    labelCentre_("FRUIT SLICER", -30, 5, [1, 0.85, 0.4, 1])
    labelCentre_("A SWIPE GAME",  30, 2, [0.85, 0.85, 0.85, 0.85])
  }

  // ── Loading ────────────────────────────────────────────────────

  updateLoading_(g) {
    _loadingThrottle = _loadingThrottle + g.dt
    if (_loadingThrottle < _loadingDelay) return
    _loadingThrottle = 0
    _loader.update(g.dt)
  }

  drawLoading_(g) {
    labelCentre_("LOADING", -40, 3, [1, 1, 1, 1])
    var barW = 400
    var barH = 16
    var barX = (FruitSlicer.DESIGN_W - barW) / 2
    var barY = FruitSlicer.DESIGN_H / 2 - barH / 2
    _hud.rect(barX, barY, barW, barH, [0.18, 0.18, 0.22, 0.9])
    _hud.rect(barX + 2, barY + 2, ((barW - 4) * _loadFraction).floor, barH - 4, [0.4, 0.85, 0.5, 1])
    var pct = (_loadFraction * 100).floor
    labelCentre_("%(pct)%", 35, 2, [0.85, 0.85, 0.85, 1])
  }

  // ── Ready ──────────────────────────────────────────────────────

  updateReady_(g) {
    if (g.input.mouseJustPressed("left")) {
      _chart.send("start")
    }
  }

  drawReady_(g) {
    labelCentre_("CLICK TO START", -25, 4, [1, 1, 1, 1])
    labelCentre_("SLICE THE FRUIT", 25, 2, [0.85, 0.85, 0.85, 1])
  }

  // ── Playing ────────────────────────────────────────────────────

  updatePlaying_(g) {
    // Clamp dt so a tab-focus-loss gap (rAF stops while the window
    // is hidden, then Browser.nextFrame.await resumes with a
    // multi-second delta) doesn't drain every fruit past the
    // bottom edge in one tick.
    var dt = g.dt
    if (dt > 0.033) dt = 0.033

    _spawnTimer = _spawnTimer - dt
    if (_spawnTimer <= 0) {
      spawn_
      _spawnTimer = randRange_(0.7, 1.4)
    }

    var i = 0
    while (i < _fruits.count) {
      var f = _fruits[i]
      f["vy"] = f["vy"] + 1500 * dt
      f["x"]  = f["x"]  + f["vx"] * dt
      f["y"]  = f["y"]  + f["vy"] * dt
      if (f["y"] > FruitSlicer.DESIGN_H + 60) {
        _fruits.removeAt(i)
        _lives = _lives - 1
        if (_lives <= 0) {
          _chart.send("gameover")
          _gameoverT = 0
        }
      } else {
        i = i + 1
      }
    }

    updateHalves_(dt)
    updateTrail_(g)
  }

  updateHalves_(dt) {
    var hi = 0
    while (hi < _halves.count) {
      var h = _halves[hi]
      h["vy"]  = h["vy"]  + 1500 * dt
      h["x"]   = h["x"]   + h["vx"] * dt
      h["y"]   = h["y"]   + h["vy"] * dt
      h["rot"] = h["rot"] + h["vrot"] * dt
      h["age"] = h["age"] + dt
      if (h["age"] > 1.0 || h["y"] > FruitSlicer.DESIGN_H + 120) {
        _halves.removeAt(hi)
      } else {
        hi = hi + 1
      }
    }
  }

  updateTrail_(g) {
    if (g.input.mouseJustPressed("left")) _trail.clear()
    if (g.input.mouseDown("left")) {
      var mx = g.input.mouseX * (FruitSlicer.DESIGN_W / g.width)
      var my = g.input.mouseY * (FruitSlicer.DESIGN_H / g.height)
      if (_trail.count > 0) {
        var p1 = _trail[_trail.count - 1]
        checkSlice_(p1["x"], p1["y"], mx, my)
        var dx = mx - p1["x"]
        var dy = my - p1["y"]
        var dist = (dx * dx + dy * dy).sqrt
        var step = 6
        var nSeg = (dist / step).floor
        if (nSeg > 1) {
          var i = 1
          while (i < nSeg) {
            var t = i / nSeg
            _trail.add({"x": p1["x"] + dx * t, "y": p1["y"] + dy * t, "age": 0})
            i = i + 1
          }
        }
      }
      _trail.add({"x": mx, "y": my, "age": 0})
      if (_trail.count > 64) _trail.removeAt(0)
    }
    var j = 0
    while (j < _trail.count) {
      _trail[j]["age"] = _trail[j]["age"] + 1
      if (_trail[j]["age"] > 16) {
        _trail.removeAt(j)
      } else {
        j = j + 1
      }
    }
  }

  drawPlaying_(g) {
    var quad = _quad

    for (f in _fruits) {
      var p = _manifest["sprites"][f["name"]]["uv"]
      quad.uv(p[0], p[1], p[2], p[3])
      quad.width  = 80
      quad.height = 80
      quad.x = f["x"]
      quad.y = f["y"]
      quad.setTint(1, 1, 1, 1)
      quad.draw(_renderer)
    }

    // Real 2D rotation on the halves through Sprite.rotation —
    // left spins CCW, right CW (vrot sign set at slice time).
    for (h in _halves) {
      var key = h["name"] + "_" + h["side"]
      var p = _manifest["halves"][key]["uv"]
      quad.uv(p[0], p[1], p[2], p[3])
      quad.rotation = h["rot"]
      quad.width  = 40
      quad.height = 80
      quad.x = h["x"]
      quad.y = h["y"]
      var alpha = 1 - h["age"]
      if (alpha < 0) alpha = 0
      quad.setTint(1, 1, 1, alpha)
      quad.draw(_renderer)
    }
    // Reset rotation so streak / HUD sprites stay axis-aligned.
    quad.rotation = 0

    drawStreak_()
    drawHud_()
  }

  drawStreak_() {
    var quad = _quad
    var streakUv = _manifest["hud"]["streak"]["uv"]
    quad.uv(streakUv[0], streakUv[1], streakUv[2], streakUv[3])
    var ti = 0
    while (ti < _trail.count) {
      var p = _trail[ti]
      var a = p["age"] / 16
      var alpha = (1 - a) * (1 - a)
      quad.x = p["x"]
      quad.y = p["y"]
      quad.width  = 14 + 6 * (1 - a)
      quad.height = 14 + 6 * (1 - a)
      quad.setTint(1, 1, 0.85, alpha)
      quad.draw(_renderer)
      ti = ti + 1
    }
  }

  drawHud_() {
    var quad = _quad
    var heartUv = _manifest["hud"]["heart"]["uv"]
    quad.uv(heartUv[0], heartUv[1], heartUv[2], heartUv[3])
    quad.width  = 32
    quad.height = 32
    quad.setTint(1, 1, 1, 1)
    var hi = 0
    while (hi < _lives) {
      quad.x = 28 + hi * 36
      quad.y = 28
      quad.draw(_renderer)
      hi = hi + 1
    }

    var digits = _score.toString
    var n = digits.count
    var startX = FruitSlicer.DESIGN_W - 16 - 24 * n + 12
    var di = 0
    while (di < n) {
      var ch = digits[di]
      var dproto = _manifest["hud"]["digits"][ch]
      quad.uv(dproto["uv"][0], dproto["uv"][1], dproto["uv"][2], dproto["uv"][3])
      quad.width  = 24
      quad.height = 24
      quad.x = startX + di * 24
      quad.y = 28
      quad.draw(_renderer)
      di = di + 1
    }
  }

  // ── Game over ──────────────────────────────────────────────────

  updateGameover_(g) {
    _gameoverT = _gameoverT + g.dt
    if (g.input.mouseJustPressed("left")) {
      resetGame_
      _chart.send("restart")
    }
  }

  drawGameover_(g) {
    // Frozen playing scene behind the overlay so halves + trail
    // settle visually behind the message.
    drawPlaying_(g)
    _renderer.flush(g.pass)
    var pulse = 0.5 + 0.5 * (_gameoverT * 4).sin
    var alpha = 0.7 + 0.3 * pulse
    labelCentre_("GAME OVER",       -30, 5, [1, 0.35, 0.35, alpha])
    labelCentre_("CLICK TO RESUME",  35, 2, [0.95, 0.85, 0.55, 0.6 + 0.4 * pulse])
  }

  // ── Error state ────────────────────────────────────────────────

  drawError_(g) {
    labelCentre_("ASSET LOAD FAILED", -25, 3, [1, 0.4, 0.4, 1])
    labelCentre_("CHECK CONSOLE",      30, 2, [0.85, 0.85, 0.85, 1])
  }

  // ── Fruit spawn + slice geometry ───────────────────────────────

  spawn_ {
    var name = _fruitNames[(rand_ * _fruitNames.count).floor]
    _fruits.add({
      "name": name,
      "x":    randRange_(80, FruitSlicer.DESIGN_W - 80),
      "y":    FruitSlicer.DESIGN_H + 40,
      "vx":   randRange_(-180, 180),
      "vy":   randRange_(-1100, -900)
    })
  }

  checkSlice_(x1, y1, x2, y2) {
    var sdx = x2 - x1
    var sdy = y2 - y1
    var sLen2 = sdx * sdx + sdy * sdy
    if (sLen2 < 64) return              // < 8 px swipe = treat as click
    var sLen = sLen2.sqrt
    var ux = sdx / sLen
    var uy = sdy / sLen
    var px = -uy
    var py =  ux
    var cutAngle = uy.atan(ux)
    var i = 0
    while (i < _fruits.count) {
      var f = _fruits[i]
      var hw = 36
      var hh = 36
      var ax = f["x"] - hw
      var ay = f["y"] - hh
      var bx = f["x"] + hw
      var by = f["y"] + hh
      if (segVsAabb_(x1, y1, x2, y2, ax, ay, bx, by)) {
        var spreadV = 280
        var followV =  60
        var spin    = randRange_(8, 14)
        _halves.add({
          "name": f["name"], "side": "left",
          "x": f["x"] + px * 14,
          "y": f["y"] + py * 14,
          "vx": f["vx"] + px * spreadV + ux * followV,
          "vy": f["vy"] + py * spreadV + uy * followV - 80,
          "age": 0, "rot": cutAngle, "vrot": -spin
        })
        _halves.add({
          "name": f["name"], "side": "right",
          "x": f["x"] - px * 14,
          "y": f["y"] - py * 14,
          "vx": f["vx"] - px * spreadV + ux * followV,
          "vy": f["vy"] - py * spreadV + uy * followV - 80,
          "age": 0, "rot": cutAngle, "vrot": spin
        })
        _fruits.removeAt(i)
        _score = _score + 1
      } else {
        i = i + 1
      }
    }
  }

  segVsAabb_(x1, y1, x2, y2, ax, ay, bx, by) {
    if (x1 < ax && x2 < ax) return false
    if (x1 > bx && x2 > bx) return false
    if (y1 < ay && y2 < ay) return false
    if (y1 > by && y2 > by) return false
    if (x1 >= ax && x1 <= bx && y1 >= ay && y1 <= by) return true
    if (x2 >= ax && x2 <= bx && y2 >= ay && y2 <= by) return true
    return segVsSeg_(x1, y1, x2, y2, ax, ay, bx, ay) ||
           segVsSeg_(x1, y1, x2, y2, bx, ay, bx, by) ||
           segVsSeg_(x1, y1, x2, y2, bx, by, ax, by) ||
           segVsSeg_(x1, y1, x2, y2, ax, by, ax, ay)
  }

  segVsSeg_(ax, ay, bx, by, cx, cy, dx, dy) {
    var d = (bx - ax) * (dy - cy) - (by - ay) * (dx - cx)
    if (d == 0) return false
    var t = ((cx - ax) * (dy - cy) - (cy - ay) * (dx - cx)) / d
    var u = ((cx - ax) * (by - ay) - (cy - ay) * (bx - ax)) / d
    return t >= 0 && t <= 1 && u >= 0 && u <= 1
  }
}

Game.run(FruitSlicer)

import "@hatch:game"    for Game
import "@hatch:gpu"     for Renderer2D, Camera2D, Sprite
import "@hatch:json"    for JSON
import "@hatch:physics" for World2D, Collider2D

/// Bouncing Ball — a click-to-drop physics demo built on
/// @hatch:game + @hatch:physics. Balls fall under gravity, bounce
/// off the ground + side walls, and pick a colour from the bundled
/// 10-ball atlas. Tap anywhere on the canvas to spawn another.
///
/// Asset credits:
///   * Ball pack — bundled with the playground (`assets/bouncing-ball/`).
///
/// Features:
///   * Texture atlas + JSON manifest fetched at startup via
///     Browser.fetchBytes / Browser.fetch. One Sprite per ball,
///     UV region set from the atlas manifest — Renderer2D batches
///     by texture so the entire frame ships in a single draw call.
///   * Real 2D physics through rapier (statically linked into the
///     wasm runtime via @hatch:physics). Gravity, restitution,
///     and side-wall collisions are real, not faked.
///   * The ground band reuses the atlas's `white` cell so we don't
///     need a separate procedural texture upload.
class Ball {
  construct new(body, name) {
    _body = body
    _name = name
    _rot  = 0
  }
  body { _body }
  name { _name }
  rot  { _rot }
  rot=(v) { _rot = v }
}

class BouncingBall is Game {
  construct new() {}

  config { {
    "title":      "Bouncing Ball",
    "width":      640,
    "height":     480,
    "clearColor": [0.05, 0.06, 0.10, 1.0],
    "canvas":     "stage-canvas"
  } }

  setup(g) {
    _renderer = Renderer2D.new(g.device, g.surfaceFormat)
    _camera   = Camera2D.new(g.width, g.height)
    _balls    = []
    _ballNames = [
      "ball_01", "ball_02", "ball_03", "ball_04", "ball_05",
      "ball_06", "ball_07", "ball_08", "ball_09", "ball_10"
    ]
    _colorIdx = 0

    // Atlas + manifest — bytes for the texture, JSON for the
    // sprite-name → UV lookup table. Same idiom Fruit Slicer uses.
    var bytes    = Browser.fetchBytes("./assets/bouncing-ball/atlas.rgba8").await
    var jsonText = Browser.fetch("./assets/bouncing-ball/atlas.json").await
    _manifest = JSON.parse(jsonText)
    var size = _manifest["size"]
    _atlasW = size[0]
    _atlasH = size[1]

    _atlas = g.device.createTexture({
      "width":  _atlasW, "height": _atlasH,
      "format": "rgba8unorm",
      "usage":  ["texture-binding", "copy-dst"]
    })
    g.device.writeTexture(_atlas, bytes, {
      "width": _atlasW, "height": _atlasH, "bytesPerRow": _atlasW * 4
    })

    // One reusable Sprite — set UV + position per draw, Renderer2D
    // collapses everything into a single draw call because the
    // texture handle never changes.
    _quad = Sprite.new(_atlas)
    _quad.anchor(0.5, 0.5)

    // Pixels-per-metre. Physics works in metres; we render in
    // pixels and scale at the boundary.
    _ppm = 50

    // Gravity points down in physics-space (-Y). The renderer
    // uses screen coords (+Y down), so we flip on the way out.
    _world = World2D.new({"gravity": [0, -9.81]})

    // Place the ground so its top edge sits exactly on the bottom
    // of the visible screen, and side walls so balls can't drift
    // off-screen on resize. Computed from the screen size + ppm
    // so the visuals stay aligned with the physics state.
    _groundHalf = 0.4
    _wallHalf   = 0.5
    var halfH = (g.height / 2) / _ppm
    var halfW = (g.width  / 2) / _ppm
    _groundY  = -halfH + _groundHalf

    _world.spawnStatic({
      "position": [0, _groundY],
      "shape":    Collider2D.box(halfW + 2, _groundHalf, {"restitution": 0.6})
    })
    _world.spawnStatic({
      "position": [-halfW - _wallHalf, 0],
      "shape":    Collider2D.box(_wallHalf, halfH * 2, {"restitution": 0.4})
    })
    _world.spawnStatic({
      "position": [ halfW + _wallHalf, 0],
      "shape":    Collider2D.box(_wallHalf, halfH * 2, {"restitution": 0.4})
    })

    // Drop a few seed balls so the demo has motion on first paint.
    // Spaced > one ball-diameter apart so the rapier solver doesn't
    // fire them apart on the first step from overlapping spawns.
    var seeds = [
      [-3.0, 4.0],
      [-1.5, 5.0],
      [ 0.0, 6.0],
      [ 1.5, 5.0],
      [ 3.0, 4.0]
    ]
    for (p in seeds) spawnBallAt_(p[0], p[1])
  }

  resize(g, w, h) {
    _camera = Camera2D.new(w, h)
  }

  update(g) {
    if (g.input.justPressed("Escape")) g.requestQuit
    if (g.input.mouseJustPressed("left")) {
      // Convert mouse pixels → world metres around screen centre.
      var wx = (g.input.mouseX - g.width / 2) / _ppm
      var wy = (g.height / 2 - g.input.mouseY) / _ppm
      spawnBallAt_(wx, wy)
    }

    _world.step(g.dt)

    // Roll the balls visually from their linear velocity.
    // omega = vx / radius (pure rolling); we integrate per frame.
    // 0.4 is the spawn-time radius in metres — kept in sync with
    // spawnBallAt_'s collider.
    for (b in _balls) {
      var v = _world.linearVelocity(b.body)
      b.rot = b.rot + v[0] * g.dt / 0.4
    }

    // Cull balls that escaped the world (shouldn't happen with
    // walls, but guards against penetration corner-cases).
    var halfW = (g.width  / 2) / _ppm + 5
    var alive = []
    for (b in _balls) {
      var p = _world.position(b.body)
      if (p[0] > -halfW && p[0] < halfW && p[1] > _groundY - 5) {
        alive.add(b)
      } else {
        _world.despawn(b.body)
      }
    }
    _balls = alive
  }

  draw(g) {
    _renderer.beginFrame(_camera)
    var quad = _quad

    // Ground band — uses the atlas's `white` cell tinted to a
    // muted slate. Same texture as the balls so the whole frame
    // batches into one draw call.
    var groundTopWorld = _groundY + _groundHalf
    var groundTopScreen = g.height / 2 - groundTopWorld * _ppm
    var whiteUV = _manifest["sprites"]["white"]["uv"]
    quad.uv(whiteUV[0], whiteUV[1], whiteUV[2], whiteUV[3])
    quad.rotation = 0
    quad.anchor(0, 0)
    quad.x = 0
    quad.y = groundTopScreen
    quad.width  = g.width
    quad.height = g.height - groundTopScreen
    quad.setTint(0.30, 0.32, 0.40, 1.0)
    quad.draw(_renderer)

    // Balls — pick the per-ball UV region from the atlas, draw at
    // physics position. Anchor returns to centre so position is
    // the ball centre in screen pixels.
    quad.anchor(0.5, 0.5)
    var px = 0.4 * 2 * _ppm
    quad.width  = px
    quad.height = px
    quad.setTint(1, 1, 1, 1)
    for (b in _balls) {
      var uv = _manifest["sprites"][b.name]["uv"]
      quad.uv(uv[0], uv[1], uv[2], uv[3])
      var p = _world.position(b.body)
      quad.x = g.width / 2 + p[0] * _ppm
      quad.y = g.height / 2 - p[1] * _ppm
      quad.rotation = b.rot
      quad.draw(_renderer)
    }
    _renderer.flush(g.pass)
  }

  spawnBallAt_(wx, wy) {
    var radius = 0.4
    var body = _world.spawnDynamic({
      "position": [wx, wy],
      "shape":    Collider2D.ball(radius, {"restitution": 0.78}),
      "mass":     1
    })
    var name = _ballNames[_colorIdx % _ballNames.count]
    _colorIdx = _colorIdx + 1
    _balls.add(Ball.new(body, name))
  }
}

Game.run(BouncingBall)

// ECS Cubes — Phase 2 exit-gate demo for the game-parity plan.
//
//   wlift main.wren
//
// 100 cubes raining onto a ground plane. Every entity is a pure
// composition of ECS components — game code never touches a Mat4
// directly. Three systems close the loop:
//
//   PhysicsSystem3D.step(world, physics, dt)   // rapier advance + writeback
//   TransformPropagation.run(world)            // Transform → GlobalTransform
//   SceneRenderer3D.run(world, camera, ...)    // (GT, MeshRenderer) → draws
//
// The renderer queries the same ECS world the physics step
// mutates; lights live as `(Transform, DirectionalLight)` /
// `AmbientLight` entities and the bridge collects them per frame.

import "@hatch:game"    for Game, Transform, MeshRenderer, RigidBody, Collider,
                            PhysicsSystem3D, TransformPropagation, SceneRenderer3D,
                            DirectionalLight, AmbientLight
import "@hatch:gpu"     for Renderer3D, Camera3D, Mesh, Material
import "@hatch:ecs"     for World
import "@hatch:math"    for Vec3, Vec4, Quat
import "@hatch:physics" for World3D, Collider3D
import "@hatch:random"  for Rand

class EcsCubes is Game {
  construct new() {}

  config { {
    "title":      "ECS Cubes",
    "width":      640,
    "height":     480,
    "clearColor": [0.05, 0.07, 0.12, 1.0],
    "depth":      true,
    "canvas":     "stage-canvas",
  } }

  setup(g) {
    _world    = World.new()
    _physics  = World3D.new()
    _renderer = Renderer3D.new(g.device, g.surfaceFormat, g.depthFormat)

    _eye    = Vec3.new(0, 14, 22)
    _target = Vec3.new(0, 2, 0)
    _fovYDeg = 55
    var aspect = g.width / g.height
    _camera = Camera3D.perspective(_fovYDeg, aspect, 0.1, 200)
    _camera.lookAt(_eye, _target, Vec3.new(0, 1, 0))

    // Shared cube mesh — every entity reuses the same vertex /
    // index buffers, so N cubes = N draws but 1 GPU upload.
    _cubeMesh   = Mesh.cube(g.device, 0.5)
    var groundMesh = Mesh.plane(g.device, 40)
    // Pre-built materials shared across every cube. Renderer3D
    // caches a GPU bind group per Material identity (UBO + 5
    // TextureViews + 1 sampler binding) — allocating a fresh
    // Material per cube leaves a pinned cache entry behind every
    // time, so a thousand spawns leaks a thousand bind groups.
    // Sharing five palette materials caps the cache at five.
    _materials = [
      buildCubeMaterial_(Vec4.new(0.92, 0.45, 0.50, 1.0)),
      buildCubeMaterial_(Vec4.new(0.45, 0.85, 0.62, 1.0)),
      buildCubeMaterial_(Vec4.new(0.45, 0.62, 0.95, 1.0)),
      buildCubeMaterial_(Vec4.new(0.95, 0.85, 0.45, 1.0)),
      buildCubeMaterial_(Vec4.new(0.80, 0.55, 0.95, 1.0)),
    ]
    // FIFO of dynamic cube entity ids — bounded so the simulation
    // stays smooth as the user spams clicks.
    _cubes      = []
    _cubeLimit  = 200
    _frameCounter = 0

    // Lights: brighter ambient + key sun + fill light. The
    // renderer collects them off the world via SceneRenderer3D's
    // per-frame walk. Without the fill light, sides facing away
    // from the sun went pitch dark — direct-light NoL = 0 plus
    // a dim ambient floor doesn't survive ACES tonemapping.
    var ambient = _world.spawn()
    _world.attach(ambient, AmbientLight.new(Vec3.new(0.55, 0.60, 0.70), 1.2))

    // Key light — warm sun coming down + forward.
    var sun = _world.spawn()
    var sunT = Transform.new()
    sunT.rotation = Quat.fromAxisAngle(Vec3.unitX, -0.7)
    _world.attach(sun, sunT)
    _world.attach(sun, DirectionalLight.new(Vec3.new(1.0, 0.95, 0.85), 4.0))

    // Fill light — cooler tone from camera-right, almost flat,
    // so the back/side faces of dynamic cubes register against
    // the dark backdrop.
    var fill = _world.spawn()
    var fillT = Transform.new()
    fillT.rotation = Quat.fromAxisAngle(Vec3.unitY, 1.2) * Quat.fromAxisAngle(Vec3.unitX, -0.3)
    _world.attach(fill, fillT)
    _world.attach(fill, DirectionalLight.new(Vec3.new(0.55, 0.70, 0.95), 1.5))

    // Static ground plane — Transform + MeshRenderer for the
    // visual, RigidBody + Collider for collision.
    var ground = _world.spawn()
    _world.attach(ground, Transform.translation(0, -0.05, 0))
    _world.attach(ground, MeshRenderer.new(groundMesh, groundMaterial_()))
    _world.attach(ground, RigidBody.new("static"))
    _world.attach(ground, Collider.new(Collider3D.box(40, 0.05, 40, {
      "restitution": 0.4, "friction": 0.9
    })))

    // Triage scene — three cubes. Used to isolate whether the
    // host's per-frame allocation pattern explodes regardless of
    // entity count; if memory still climbs with three, the leak
    // is in the per-frame plumbing (queue write, command record,
    // GC marking) rather than scaling with cube count.
    var i = 0
    while (i < 3) {
      spawnCubeAt_(Rand.float(-4, 4), Rand.float(6, 12), Rand.float(-4, 4))
      i = i + 1
    }
  }

  resize(g, w, h) {
    _camera.setPerspective(_fovYDeg, w / h, 0.1, 200)
  }

  update(g) {
    if (g.input.justPressed("Escape")) g.requestQuit
    if (g.input.mouseJustPressed("left")) dropCubeAtCursor_(g)

    // Clamp dt to dodge giant single-step blow-ups when the tab
    // un-pauses or the first frame's wall-time is wonky.
    var dt = g.dt
    if (dt > 1.0 / 30) dt = 1.0 / 30

    PhysicsSystem3D.step(_world, _physics, dt)
    TransformPropagation.run(_world)

    // Triage: nudge the GC every 30 frames (~2x per sec) so
    // short-lived per-frame allocations don't get promoted to
    // old gen. If the leak is host-side (wgpu / Metal driver),
    // this is a no-op; if it's Wren-side, this should keep RSS
    // flat under steady idle.
    _frameCounter = _frameCounter + 1
    if (_frameCounter >= 30) {
      _frameCounter = 0
      System.gc()
    }
  }

  draw(g) {
    SceneRenderer3D.run(_world, _camera, _renderer, g.pass)
  }

  // Ground material — desaturated dielectric, slightly rough.
  groundMaterial_() {
    var m = Material.new(Vec4.new(0.30, 0.32, 0.35, 1.0))
    m.roughnessFactor = 0.85
    m.metallicFactor  = 0.0
    return m
  }

  // Build one of the cube's shared palette materials. Stored
  // once at setup; every cube references whichever one the
  // palette picks for it.
  buildCubeMaterial_(albedo) {
    var m = Material.new(albedo)
    m.roughnessFactor = 0.55
    m.metallicFactor  = 0.1
    return m
  }

  // Spawn one dynamic cube entity at (x, y, z) with a randomly
  // picked palette material. Appends to `_cubes` (a FIFO) and
  // evicts the oldest cube when `_cubeLimit` is exceeded so the
  // sim stays smooth under sustained clicking.
  spawnCubeAt_(x, y, z) {
    var e = _world.spawn()
    _world.attach(e, Transform.translation(x, y, z))
    _world.attach(e, MeshRenderer.new(_cubeMesh, _materials[Rand.int(_materials.count)]))

    var rb = RigidBody.new("dynamic", 1.0)
    rb.linearVelocity = Vec3.new(Rand.float(-1, 1), 0, Rand.float(-1, 1))
    _world.attach(e, rb)
    _world.attach(e, Collider.new(Collider3D.box(0.5, 0.5, 0.5, {
      "restitution": 0.35, "friction": 0.6
    })))

    _cubes.add(e)
    if (_cubes.count > _cubeLimit) {
      var oldest = _cubes.removeAt(0)
      var oldRb = _world.get(oldest, RigidBody)
      if (oldRb != null && oldRb.bodyId != null) _physics.despawn(oldRb.bodyId)
      _world.despawn(oldest)
    }
    return e
  }

  // Spawn a cube at the cursor's 3D position — the screen point
  // is unprojected through the camera's focal plane (the plane
  // through `_target` perpendicular to the view direction), so
  // dragging the cursor up the screen lifts the spawn point and
  // dragging it down drops it closer to the ground. Cubes that
  // would spawn underground get clamped to half their height
  // above the floor so they don't tunnel through the collider.
  dropCubeAtCursor_(g) {
    var hit = cursorInFocalPlane_(g)
    if (hit == null) return
    var y = hit.y
    if (y < 0.5) y = 0.5
    spawnCubeAt_(hit.x, y, hit.z)
  }

  // Build a world-space ray through the cursor + intersect with
  // the plane through `_target` whose normal is the camera's
  // forward axis. Skips `Mat4.inverse` (not yet exposed by
  // @hatch:math) by working in the camera basis directly.
  cursorInFocalPlane_(g) {
    // NDC: x ∈ [-1, 1], y flipped so screen-top maps to +Y.
    var ndcX = (g.input.mouseX / g.width)  * 2 - 1
    var ndcY = 1 - (g.input.mouseY / g.height) * 2
    var aspect = g.width / g.height
    // Frustum half-extents at unit distance from the camera.
    var halfV = ((_fovYDeg * 0.017453292519943295) / 2).tan   // π/180
    var halfH = halfV * aspect

    // Camera basis. Forward = target - eye, right = forward × up,
    // up = right × forward.
    var fwd   = (_target - _eye).normalized
    var right = fwd.cross(Vec3.new(0, 1, 0)).normalized
    var up    = right.cross(fwd)

    // Ray direction in world space.
    var dir = (fwd + right * (ndcX * halfH) + up * (ndcY * halfV)).normalized

    // Intersect with the plane through `_target` whose normal is
    // `fwd`. t = ((target - eye) · fwd) / (dir · fwd).
    var denom = dir.dot(fwd)
    if (denom.abs < 0.0001) return null
    var t = (_target - _eye).dot(fwd) / denom
    if (t < 0) return null
    return _eye + dir * t
  }
}

Game.run(EcsCubes)

import "@hatch:assert" for Expect

// `Future`, `Browser`, `WebSocket`, `Dom`, `LocalStorage` are
// loaded by the runtime — no boilerplate needed. Async bridges
// resume through the scheduler in both modes; print *inside*
// the fiber so results land in the output pane.

var fiber = Fiber.new {
  System.print("before: %(Dom.text("#title").await)")
  Browser.setTimeout(0).await
  Dom.setText("#title", "rewritten by wren").await
  Dom.setText("#msg", "scheduler resumed me after 0ms").await
  Dom.addClass("#title", "dim").await
  System.print("done")
}
fiber.try()

// Recursive compute through the wasm tier-up JIT. fib(20) lands
// at ~3 ms post-warmup on both worker and main mode.
var start = System.clock
var fib
fib = Fn.new {|n| n < 2 ? n : fib.call(n - 1) + fib.call(n - 2) }
var result = fib.call(20)
var elapsed = (System.clock - start) * 1000

Expect.that(result).toBe(6765)
var hundredths = (elapsed * 100).round
var whole = (hundredths / 100).floor
var frac = hundredths - whole * 100
var fracStr = frac < 10 ? "0%(frac)" : "%(frac)"
System.print("fib(20) = %(result)  (%(whole).%(fracStr) ms)")

import "@hatch:sqlite" for Database

/// Books catalogue — a small in-memory SQLite demo. Builds a
/// `books` table from a 15-row seed list, runs three queries
/// that show off real SQL (parameter binding, GROUP BY
/// aggregates, HAVING-filtered groupwise summaries), and paints
/// the results into the stage panel as HTML tables.
///
/// Memory VFS only — closing the page wipes the database. The
/// playground links sqlite-wasm-rs directly into wlift_wasm so
/// no external runtime is fetched.

class Html {
  /// Escape a single value for safe HTML interpolation. Numbers
  /// pass straight through (one decimal place for non-integers
  /// so 4.5 reads as `4.5` instead of `4.5000`); everything else
  /// escapes the four metacharacters that matter inside text +
  /// attribute contexts (`& < > "`).
  static cell(v) {
    if (v == null) return "&mdash;"
    if (v is Num) {
      if (v == v.floor) return v.toString
      var rounded = (v * 10).round / 10
      var s = rounded.toString
      if (!s.contains(".")) s = s + ".0"
      return s
    }
    return Html.escape(v.toString)
  }

  static escape(s) {
    var out = ""
    for (i in 0...s.count) {
      var c = s[i]
      if (c == "&") {
        out = out + "&amp;"
      } else if (c == "<") {
        out = out + "&lt;"
      } else if (c == ">") {
        out = out + "&gt;"
      } else if (c == "\"") {
        out = out + "&quot;"
      } else {
        out = out + c
      }
    }
    return out
  }

  /// Render `(rows, keys, headers)` as an HTML table. `numericKeys`
  /// is the subset of keys whose cells should right-align under
  /// numeric headers; the page CSS picks them up via `td.num`.
  static table(headers, rows, keys, numericKeys) {
    var html = "<table><thead><tr>"
    for (h in headers) {
      html = html + "<th>" + Html.escape(h) + "</th>"
    }
    html = html + "</tr></thead><tbody>"
    for (row in rows) {
      html = html + "<tr>"
      for (i in 0...keys.count) {
        var cls = numericKeys.contains(keys[i]) ? " class=\"num\"" : ""
        html = html + "<td" + cls + ">" + Html.cell(row[keys[i]]) + "</td>"
      }
      html = html + "</tr>"
    }
    return html + "</tbody></table>"
  }
}

var fiber = Fiber.new {
  var db = Database.openMemory()

  db.execute(
    "CREATE TABLE books (" +
    "  id     INTEGER PRIMARY KEY," +
    "  title  TEXT NOT NULL," +
    "  author TEXT NOT NULL," +
    "  year   INTEGER NOT NULL," +
    "  rating REAL NOT NULL" +
    ")"
  )

  // Seed rows. Wrapping the 15 inserts in a transaction commits
  // them in one shot — without it each INSERT pays a separate
  // fsync-equivalent on a real on-disk DB.
  var seed = [
    ["Beloved",                       "Toni Morrison",          1987, 4.5],
    ["Things Fall Apart",             "Chinua Achebe",          1958, 4.4],
    ["One Hundred Years of Solitude", "Gabriel Garcia Marquez", 1967, 4.6],
    ["Love in the Time of Cholera",   "Gabriel Garcia Marquez", 1985, 4.3],
    ["Mrs Dalloway",                  "Virginia Woolf",         1925, 4.1],
    ["To the Lighthouse",             "Virginia Woolf",         1927, 4.2],
    ["The Sound and the Fury",        "William Faulkner",       1929, 4.0],
    ["Invisible Man",                 "Ralph Ellison",          1952, 4.5],
    ["The Bluest Eye",                "Toni Morrison",          1970, 4.3],
    ["Song of Solomon",               "Toni Morrison",          1977, 4.4],
    ["Kafka on the Shore",            "Haruki Murakami",        2002, 4.2],
    ["Norwegian Wood",                "Haruki Murakami",        1987, 4.4],
    ["The Underground Railroad",      "Colson Whitehead",       2016, 4.4],
    ["The Nickel Boys",               "Colson Whitehead",       2019, 4.3],
    ["Pachinko",                      "Min Jin Lee",            2017, 4.5]
  ]

  db.transaction {
    for (b in seed) {
      db.execute(
        "INSERT INTO books (title, author, year, rating) VALUES (?, ?, ?, ?)",
        b
      )
    }
  }

  Dom.setText("#meta",
    "%(seed.count) rows inserted · last rowid %(db.lastInsertRowid) · " +
    "in transaction now: %(db.inTransaction)").await

  // --- Query 1: top-rated since 1980 --------------------------
  var q1 = db.query(
    "SELECT title, author, year, rating " +
    "FROM books " +
    "WHERE year >= ? " +
    "ORDER BY rating DESC, year ASC " +
    "LIMIT 5",
    [1980]
  )
  Dom.setHTML("#q1", Html.table(
    ["title", "author", "year", "rating"], q1,
    ["title", "author", "year", "rating"], ["year", "rating"]
  )).await

  // --- Query 2: aggregate by decade ---------------------------
  var q2 = db.query(
    "SELECT (year/10)*10 AS decade, " +
    "       COUNT(*)     AS books, " +
    "       AVG(rating)  AS avg_rating " +
    "FROM books " +
    "GROUP BY decade " +
    "ORDER BY decade"
  )
  Dom.setHTML("#q2", Html.table(
    ["decade", "books", "avg rating"], q2,
    ["decade", "books", "avg_rating"], ["decade", "books", "avg_rating"]
  )).await

  // --- Query 3: authors with multiple titles ------------------
  var q3 = db.query(
    "SELECT author, " +
    "       COUNT(*)        AS titles, " +
    "       AVG(rating)     AS avg_rating, " +
    "       MIN(year)       AS first_year, " +
    "       MAX(year)       AS last_year " +
    "FROM books " +
    "GROUP BY author " +
    "HAVING COUNT(*) > 1 " +
    "ORDER BY titles DESC, avg_rating DESC"
  )
  Dom.setHTML("#q3", Html.table(
    ["author", "titles", "avg", "first", "last"], q3,
    ["author", "titles", "avg_rating", "first_year", "last_year"],
    ["titles", "avg_rating", "first_year", "last_year"]
  )).await

  db.close
}
fiber.try()

import "@hatch:math"   for Vec3, Mat4, Quat, Math
import "@hatch:assert" for Expect

// Helper — String interpolation of a Vec3 lands on the default
// "instance of Vec3" toString today, so we render fields by hand.
var fmt = Fn.new {|v| "(%(v.x), %(v.y), %(v.z))" }

var a = Vec3.new(1, 2, 3)
var b = Vec3.new(4, 5, 6)

System.print("a       = %(fmt.call(a))")
System.print("b       = %(fmt.call(b))")
System.print("a + b   = %(fmt.call(a + b))")
System.print("a · b   = %(a.dot(b))")
System.print("a × b   = %(fmt.call(a.cross(b)))")
System.print("|a|     = %(a.length)")

// Mat4.translation takes three components, not a Vec3.
var m = Mat4.translation(10, 0, 0)
var p = m.transformPoint(a)
System.print("translated a → %(fmt.call(p))")
Expect.that(p.x).toBe(11)

// Quaternion rotation 90° around Y.
var q = Quat.fromAxisAngle(Vec3.new(0, 1, 0), Math.radians(90))
var r = q.rotateVec3(Vec3.new(1, 0, 0))
// (1,0,0) rotated 90° around Y → (0, 0, -1) (within float epsilon).
System.print("rotated x-hat by 90°/Y → %(fmt.call(r))")
Expect.that(Math.approxEq(r.z, -1, 0.001)).toBe(true)
System.print("✓ all assertions pass")

import "@hatch:assert" for Expect

// SIMD — fixed-width 4-lane Simd4f / Simd4i values.
//
// Both classes share the same 16-byte storage; bitcast via
// `reinterpretAsInt` / `reinterpretAsFloat`. Arithmetic +, -, *,
// /, min, max and comparisons all return new immutable values.
// On a browser that supports the wasm SIMD proposal the runtime
// routes every op through `simd128` instructions; older browsers
// still get the same answers via the scalar fallback.

// Lane-wise arithmetic. `+(_)`, `-(_)`, `*(_)`, `/(_)` are real
// Wren operators on Simd4f.
var a = Simd4f.new(1.0, 2.0, 3.0, 4.0)
var b = Simd4f.new(0.5, 1.5, 2.5, 3.5)
var sum = a + b
System.print("a       = %(a)")
System.print("b       = %(b)")
System.print("a + b   = %(sum)")
Expect.that(sum[0]).toBe(1.5)
Expect.that(sum[3]).toBe(7.5)

// Dot product: lane-wise multiply, then horizontal add.
var prod = a * b
var dot  = prod[0] + prod[1] + prod[2] + prod[3]
System.print("a . b   = %(dot)")
Expect.that(dot).toBe(25.0)

// Splat broadcasts a scalar to every lane. Composition with
// `min` / `max` clips a lane-wise computation in one expression.
var clipped = (a * Simd4f.splat(2.5)).min(Simd4f.splat(8.0))
System.print("clip(2.5*a, 8) = %(clipped)")
Expect.that(clipped[2]).toBe(7.5)
Expect.that(clipped[3]).toBe(8.0)

// Comparison -> lane mask. `bitmask` packs the MSB of each lane
// into bit i (lane 0 -> bit 0, etc.) so four bool lanes round-trip
// through a single Num.
var ints = Simd4i.new(1, 5, 3, 7)
var mask = ints > Simd4i.splat(4)
System.print("ints    = %(ints)")
System.print("ints > 4: bitmask = %(mask.bitmask)")
Expect.that(mask.bitmask).toBe(10)             // lanes 1 + 3 set -> 0b1010

// Float32Array round-trip — the data path you would use to stream
// SIMD-shaped values out to a plugin or GPU buffer.
var buf = Float32Array.fromList([0, 0, 0, 0, 9, 9, 9, 9])
sum.store(buf, 0)
var loaded = Simd4f.load(buf, 0) + Simd4f.load(buf, 4)
System.print("buf round-trip -> %(loaded)")
Expect.that(loaded[0]).toBe(10.5)              // 1.5 + 9
Expect.that(loaded[3]).toBe(16.5)              // 7.5 + 9

// ----------------------------------------------------------------
// Throughput demo — getting the tier-up JIT to actually fire.
// ----------------------------------------------------------------
//
// The wasm tier-up promotes hot *functions*, not hot *loops*. A
// loop sitting at module top-level (the script's once-invoked
// outer fiber) never crosses the call-count threshold, so the
// body would stay in the bytecode interpreter forever. The
// pattern that actually exercises the JIT: wrap the hot work in
// a closure / method, call it many times, let the runtime
// promote the closure on the ~50th invocation, and the
// remaining invocations run through JIT'd wasm.
//
// Inside the JIT'd closure each `acc + STEP` lowers to inline
// `f64.add` for Num operands (the common case) or a direct
// `wren_simd4f_add` helper call for Simd4f operands — bypassing
// the full method-dispatch chain.

var STEP = Simd4f.new(0.001, 0.002, 0.003, 0.004)

// Single-arg closure body: 100 SIMD adds per call. Tier-up'd
// after the wasm JIT threshold (currently 50 calls), so the
// inner loop runs as native wasm with the SIMD class-guard
// fast path picked up in the helper.
var batch = Fn.new {|acc|
  var j = 0
  while (j < 100) {
    acc = acc + STEP
    j = j + 1
  }
  return acc
}

var iters = 1000          // 1000 outer calls × 100 inner adds = 100k total
var acc1  = Simd4f.splat(0.0)
var t0 = System.clock
var i = 0
while (i < iters) {
  acc1 = batch.call(acc1)
  i = i + 1
}
var pass1 = (System.clock - t0) * 1000

// Pass 2: closure has tiered up by now, so this measurement is
// the steady-state JIT'd cost. Compare against pass 1 to see
// the warm-up tax (BC-interpreted first ~50 calls + the
// compile + the rest as JIT).
var acc2  = Simd4f.splat(0.0)
var t1 = System.clock
i = 0
while (i < iters) {
  acc2 = batch.call(acc2)
  i = i + 1
}
var pass2 = (System.clock - t1) * 1000

System.print("simd batch x %(iters) (100 adds each):")
System.print("  pass 1 (incl. warm-up): %(pass1) ms")
System.print("  pass 2 (steady-state):  %(pass2) ms")
System.print("  acc                  -> %(acc2)")

System.print("SIMD example complete")

import "@hatch:assert" for Expect

// fib(20) recursive compute through the wasm tier-up JIT.
//
// fib's body — `fib.call(n - 1) + fib.call(n - 2)` — promotes
// to a per-function wasm module after ~50 invocations. From
// then on every recursive call goes through the JIT slot
// table via inline `call_indirect`, and the module-var read
// of `fib` lowers to a 3-instruction `i32.load + i64.load`
// pair instead of a wasm-bindgen boundary call. ~13.5k
// recursive frames per fib(20), entirely in wasm.

var fib
fib = Fn.new {|n| n < 2 ? n : fib.call(n - 1) + fib.call(n - 2) }

// Warm up so the timed pass measures steady-state JIT cost,
// not the first-50-call BC interpreter + compile cost.
fib.call(20)

// 100x fib(20) lifts the timing into a stable range — single
// fib(20) lands sub-millisecond on modern hardware, below the
// resolution `performance.now()` reports back to Wren. Bump
// `iters` if you want a louder signal, or change `fib.call(20)`
// to `fib.call(28)` if you want to feel the runtime in earnest.
var iters = 100
var t0 = System.clock
var i = 0
while (i < iters) {
  fib.call(20)
  i = i + 1
}
var elapsed = (System.clock - t0) * 1000
var perCall = elapsed / iters

Expect.that(fib.call(20)).toBe(6765)

System.print("fib(20) = 6765")
System.print("x %(iters) calls (post warm-up):")
System.print("  total:    %(elapsed) ms")
System.print("  per call: %(perCall) ms")

import "@hatch:assert" for Expect

// Closure upvalue capture benchmark.
//
// `Adder.new(base)` builds a closure that captures `base` from
// the constructor's local scope and reads it on every call. The
// body — `Fn.new {|x| base + x}` — has one `GetUpvalue` per
// invocation; with the inline lowering it lands as an inline
// `i32.load` chain through the closure -> upvalues data ptr ->
// `*mut ObjUpvalue` -> location -> `*Value` instead of a
// wasm-bindgen boundary call into `wren_get_upvalue`.

class Adder {
  construct new(base) {
    _add = Fn.new {|x| base + x }
  }
  add(x) { _add.call(x) }
}

var a = Adder.new(100)

// Warm-up so the timed pass measures steady-state JIT cost,
// not the first-50-call BC interpreter + compile cost.
a.add(5)

var iters = 100000
var t0 = System.clock
var i = 0
var sum = 0
while (i < iters) {
  sum = sum + a.add(i)
  i = i + 1
}
var elapsed = (System.clock - t0) * 1000
var perCall = elapsed / iters

// 100 + i for i in 0..iters: sum is base*iters + (iters-1)*iters/2.
var expected = 100 * iters + (iters - 1) * iters / 2
Expect.that(sum).toBe(expected)

System.print("Adder.add (read-only capture) x %(iters):")
System.print("  total:    %(elapsed) ms")
System.print("  per call: %(perCall) ms")
System.print("  sum:      %(sum)")

// ----------------------------------------------------------------
// Mutating-capture variant — `n = n + 1` is a SetUpvalue. With
// the inline lowering it does the same chase as GetUpvalue plus
// an `i64.store` through `*location`, then one `wren_write_
// barrier` boundary call for the GC inter-generational write
// tracking (which is fundamental GC state — the JIT can't elide
// it). Per-call cost is therefore ~one boundary crossing higher
// than the read-only Adder above.
// ----------------------------------------------------------------

class Counter {
  construct new(initial) {
    var n = initial
    _next = Fn.new {
      n = n + 1
      return n
    }
  }
  next { _next.call() }
}

var c = Counter.new(0)
c.next  // warm-up

var miters = 10000
var t1 = System.clock
var j = 0
while (j < miters) {
  c.next
  j = j + 1
}
var mElapsed = (System.clock - t1) * 1000

System.print("")
System.print("Counter.next (mutating capture) x %(miters):")
System.print("  total:    %(mElapsed) ms")
System.print("  per call: %(mElapsed / miters) ms")
System.print("  final:    %(c.next - 1)  (= %(miters))")

import "@hatch:ecs"    for World
import "@hatch:assert" for Expect

class Position {
  construct new(x, y) {
    _x = x
    _y = y
  }
  x { _x }
  x=(v) { _x = v }
  y { _y }
  y=(v) { _y = v }
  toString { "(%(_x), %(_y))" }
}

class Velocity {
  construct new(x, y) {
    _x = x
    _y = y
  }
  x { _x }
  y { _y }
}

class Tag {
  construct new(name) {
    _name = name
  }
  name { _name }
}

var w = World.new()

// Spawn three entities, attach component bundles.
var alice = w.spawn()
w.attach(alice, Position.new(0, 0))
w.attach(alice, Velocity.new(1, 2))
w.attach(alice, Tag.new("alice"))

var bob = w.spawn()
w.attach(bob, Position.new(10, 5))
w.attach(bob, Velocity.new(-1, 0))
w.attach(bob, Tag.new("bob"))

// Static entity — no Velocity component.
var rock = w.spawn()
w.attach(rock, Position.new(50, 50))
w.attach(rock, Tag.new("rock"))

System.print("world has %(w.count) entities")
Expect.that(w.count).toBe(3)

// Fluent query builder is reached via World.query (not Query.new).
// .iterate runs the filter and returns an iterable; for-in does
// the rest.
for (e in w.query.with(Position).with(Velocity).iterate) {
  var p = w.get(e, Position)
  var v = w.get(e, Velocity)
  p.x = p.x + v.x
  p.y = p.y + v.y
}

for (e in w.query.with(Position).with(Tag).iterate) {
  var name = w.get(e, Tag).name
  var p    = w.get(e, Position)
  System.print("  %(name): %(p)")
}

Expect.that(w.get(alice, Position).x).toBe(1)
Expect.that(w.get(rock, Position).x).toBe(50)  // no velocity → static
System.print("✓ motion + static both as expected")

import "@hatch:game" for Game
import "@hatch:gpu"  for Renderer2D, Camera2D, Sprite

class SpriteGrid is Game {
  construct new() {}

  config { {
    "title":      "Sprite Grid",
    "width":      640,
    "height":     480,
    "clearColor": [0.04, 0.05, 0.08, 1.0],
    // Web-only: attach to the existing <canvas> in the playground
    // stage instead of spawning a fresh one. Ignored on native.
    "canvas":     "stage-canvas"
  } }

  setup(g) {
    _renderer = Renderer2D.new(g.device, g.surfaceFormat)
    _camera   = Camera2D.contain(640, 480, g.width, g.height)

    // Solid-white 8×8 atlas built byte-by-byte. Sidesteps
    // `@hatch:image` (which has no web cdylib today). Sprites
    // tint the atlas via vertex colour, so a single texture
    // backs the whole rainbow grid.
    var w = 8
    var h = 8
    var bytes = ""
    var i = 0
    while (i < w * h * 4) {
      bytes = bytes + String.fromCodePoint(255)
      i = i + 1
    }
    _texture = g.device.createTexture({
      "width":  w, "height": h,
      "format": "rgba8unorm",
      "usage":  ["texture-binding", "copy-dst"]
    })
    g.device.writeTexture(_texture, bytes, {
      "width": w, "height": h, "bytesPerRow": w * 4
    })

    _cols = 18
    _rows = 14
    _cell = 28
    _offsetX = 0
    _offsetY = 0

    // Pre-build sprites once; positions + tints update each frame.
    _sprites = []
    var r = 0
    while (r < _rows) {
      var c = 0
      while (c < _cols) {
        var s = Sprite.new(_texture)
        s.width  = _cell - 4
        s.height = _cell - 4
        s.anchor(0.5, 0.5)
        _sprites.add(s)
        c = c + 1
      }
      r = r + 1
    }
  }

  resize(g, w, h) { _camera.fitContain(w, h) }

  update(g) {
    if (g.input.justPressed("Escape")) g.requestQuit
    var speed = 200 * g.dt
    if (g.input.isDown("KeyA") || g.input.isDown("ArrowLeft"))  _offsetX = _offsetX - speed
    if (g.input.isDown("KeyD") || g.input.isDown("ArrowRight")) _offsetX = _offsetX + speed
    if (g.input.isDown("KeyW") || g.input.isDown("ArrowUp"))    _offsetY = _offsetY - speed
    if (g.input.isDown("KeyS") || g.input.isDown("ArrowDown"))  _offsetY = _offsetY + speed
  }

  draw(g) {
    _renderer.beginFrame(_camera)
    var t = g.elapsed
    var originX = (_camera.width  - _cols * _cell) / 2 + _offsetX
    var originY = (_camera.height - _rows * _cell) / 2 + _offsetY
    var idx = 0
    var r = 0
    while (r < _rows) {
      var c = 0
      while (c < _cols) {
        var s = _sprites[idx]
        s.x = originX + c * _cell + _cell / 2
        s.y = originY + r * _cell + _cell / 2
        var phase = (c + r) * 0.25 + t * 1.5
        s.setTint(
          0.5 + 0.5 * phase.sin,
          0.5 + 0.5 * (phase + 2.094).sin,
          0.5 + 0.5 * (phase + 4.188).sin,
          1.0
        )
        s.draw(_renderer)
        idx = idx + 1
        c = c + 1
      }
      r = r + 1
    }
    _renderer.flush(g.pass)
  }
}

Game.run(SpriteGrid)

import "@hatch:window" for Window
import "@hatch:gpu"    for Gpu, Camera2D, Renderer2D

var SURF_W = 600
var SURF_H = 400

// BYO canvas — same shape main + worker honour. The page already
// owns <canvas id="stage-canvas">; `Window.create({"canvas": <id>})`
// attaches without touching the DOM, so this works in worker mode
// (where the canvas arrives via `transferControlToOffscreen`).
var window = Window.create({
  "canvas": "stage-canvas",
  "title":  "renderer2d demo"
})

var device  = Gpu.requestDevice({})
var surface = device.createSurface(window.handle)
var renderer = Renderer2D.new(device, "preferred")

// 4x4 RGBA8 white texture — sprites tint it via vertex colour
// so we don't need any image asset.
var whiteBytes = ""
var i = 0
while (i < 4 * 4 * 4) {
  whiteBytes = whiteBytes + String.fromCodePoint(255)
  i = i + 1
}
var atlas = device.createTexture({
  "width":  4, "height": 4,
  "format": "rgba8unorm",
  "usage":  ["texture-binding", "copy-dst"]
})
device.writeTexture(atlas, whiteBytes, {
  "width": 4, "height": 4, "bytesPerRow": 16
})

var camera = Camera2D.contain(SURF_W, SURF_H, SURF_W, SURF_H)
renderer.beginFrame(camera)

// 4×4 grid, four-colour rotation.
var palette = [
  [0.85, 0.48, 0.17, 1.0],
  [0.36, 0.78, 0.50, 1.0],
  [0.32, 0.55, 0.91, 1.0],
  [0.93, 0.84, 0.36, 1.0],
]
var size   = 80
var gap    = 12
var totalW = 4 * size + 3 * gap
var totalH = 4 * size + 3 * gap
var ox = (SURF_W - totalW) / 2
var oy = (SURF_H - totalH) / 2
var cell = 0
while (cell < 16) {
  var col = cell % 4
  var row = (cell / 4).floor
  var x = ox + col * (size + gap)
  var y = oy + row * (size + gap)
  var c = palette[(row + col) % 4]
  renderer.drawSpriteTinted(atlas, x, y, size, size, c[0], c[1], c[2], c[3])
  cell = cell + 1
}

var frame = surface.acquire()
var enc   = device.createCommandEncoder()
var pass  = enc.beginRenderPass({
  "colorAttachments": [{
    "view":       frame.view,
    "loadOp":     "clear",
    "clearValue": { "r": 0.06, "g": 0.05, "b": 0.04, "a": 1.0 },
    "storeOp":    "store"
  }]
})
renderer.flush(pass)
pass.end
enc.finish
device.submit([enc])
frame.present
System.print("rendered ✓ (4×4 grid)")
